export const finite=v=>(typeof v==='number'||typeof v==='string')&&String(v).trim()!==''&&Number.isFinite(Number(v));
export const avg=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:null;
export const quantile=(a,p)=>{const s=a.filter(Number.isFinite).sort((a,b)=>a-b);if(!s.length)return null;const i=(s.length-1)*p,l=Math.floor(i);return s[l]+(s[Math.ceil(i)]-s[l])*(i-l);};
export const day=s=>Date.parse(s)/86400000;
export const iso=d=>new Date(d*86400000).toISOString().slice(0,10);
export function linearModel(rows){const r=rows.filter(p=>finite(p.x)&&finite(p.y)).map(p=>({x:Number(p.x),y:Number(p.y)}));if(r.length<4)return null;const mx=avg(r.map(p=>p.x)),my=avg(r.map(p=>p.y)),sxx=r.reduce((s,p)=>s+(p.x-mx)**2,0);if(sxx<1e-12)return null;const b=r.reduce((s,p)=>s+(p.x-mx)*(p.y-my),0)/sxx,a=my-b*mx,residuals=r.map(p=>p.y-a-b*p.x),s2=residuals.reduce((s,e)=>s+e*e,0)/(r.length-2);const den=residuals.reduce((s,e)=>s+e*e,0),lag1=den?residuals.slice(1).reduce((s,e,i)=>s+e*residuals[i],0)/den:0;if(![a,b,mx,sxx,s2,lag1].every(Number.isFinite))return null;return {a,b,mx,sxx,s2,n:r.length,residuals,lag1};}
export function t95(df){const knots=[[1,12.706],[2,4.303],[3,3.182],[4,2.776],[5,2.571],[6,2.447],[7,2.365],[8,2.306],[9,2.262],[10,2.228],[12,2.179],[15,2.131],[20,2.086],[25,2.06],[30,2.042],[40,2.021],[60,2],[120,1.98],[100000,1.96]];return [...knots].reverse().find(([n])=>n<=df)?.[1]??12.706;}
export function intervalAt(m,x,{nonnegative=true}={}){if(!m||!finite(x))return {prediction:null,low95:null,high95:null,meanLow95:null,meanHigh95:null,confidence:'无法计算：有效观测不足或横坐标恒定'};const raw=m.a+m.b*x,h=1/m.n+(x-m.mx)**2/m.sxx,c=t95(m.n-2),mean=c*Math.sqrt(m.s2*h),pred=c*Math.sqrt(m.s2*(1+h)),clip=v=>nonnegative?Math.max(0,v):v;return {prediction:clip(raw),low95:clip(raw-pred),high95:clip(raw+pred),meanLow95:clip(raw-mean),meanHigh95:clip(raw+mean),confidence:Math.abs(m.lag1)>.4?'条件区间；残差自相关明显，名义覆盖率可能失准':'条件95%区间；未保证样本外覆盖率',model:'OLS线性趋势＋Student-t',assumptions:'残差近似独立、正态、同方差，且未来生产制度不变；非负截断会改变名义覆盖率'};}
export function rng(seed=42){return ()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};}
export function blockDraw(a,n,random,block=7){const out=[];if(!a.length)return out;while(out.length<n){const start=Math.floor(random()*Math.max(1,a.length-block+1));for(let j=0;j<Math.min(block,a.length)&&out.length<n;j++)out.push(a[(start+j)%a.length]);}return out;}
export function conformalInterval(results,calibration,{model='当前训练模型',alpha=.05,nonnegative=false}={}){const scores=calibration.filter(r=>finite(r.actual)&&finite(r.prediction)).map(r=>Math.abs(Number(r.actual)-Number(r.prediction))).sort((a,b)=>a-b),rank=Math.ceil((scores.length+1)*(1-alpha)),q=scores[rank-1];return results.map(r=>({...r,model_name:model,nominal_coverage:1-alpha,prediction_low95:finite(r.prediction)&&q!==undefined?(nonnegative?Math.max(0,Number(r.prediction)-q):Number(r.prediction)-q):null,prediction_high95:finite(r.prediction)&&q!==undefined?Number(r.prediction)+q:null,mean_ci_low95:null,mean_ci_high95:null,confidence_note:q===undefined?'无法计算有限95%区间：独立验证残差至少19条；不借用测试残差':'分割保形名义95%预测区间；要求验证/预测误差可交换。时序漂移、同井相关及跨井差异可能破坏覆盖率；未单独估计均值置信区间',calibration_n:scores.length}));}
